    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.SelectedStreamingFrequency
    public int SelectedStreamingFrequency
    {
        get => _selectedStreamingFrequency;
        set
        {
            if (value < 1) { return; }

            // Use IsLogging (not LoggingManager.Active) so the guard also blocks
            // changes when a connected device is reporting SD-card logging without
            // the local toggle ever having been flipped — e.g. on reconnect to a
            // device that's still logging from a previous desktop session.
            if (IsLogging)
            {
                var errorDialogViewModel = new ErrorDialogViewModel("Cannot change sampling frequency while logging.");
                _ = _dialogService.ShowDialogAsync<ErrorDialog>(this, errorDialogViewModel);
                return;
            }

            SelectedDevice.StreamingFrequency = value;
            _selectedStreamingFrequency = SelectedDevice.StreamingFrequency;
            OnPropertyChanged();
        }
    }

    // WPF SystemParameters.WorkArea → the main window's screen working area (DIP-scaled).
    private static Rect? GetMainWindowWorkArea()
    {
        if (GetMainWindow() is not { } main)
        {
            return null;
        }

        var screen = main.Screens.ScreenFromWindow(main) ?? main.Screens.Primary;
        if (screen == null)
        {
            return null;
        }

        return new Rect(0, 0, screen.WorkingArea.Width / screen.Scaling, screen.WorkingArea.Height / screen.Scaling);
    }

    private static Window? GetMainWindow()
        => Application.Current?.ApplicationLifetime is IClassicDesktopStyleApplicationLifetime { MainWindow: { } main }
            ? main
            : null;

