    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.ShowConnectionDialog
    private async Task ShowConnectionDialogAsync()
    {
        var dialogVm = new ConnectionDialogViewModel();
        _connectionDialogViewModel = dialogVm;
        try
        {
            dialogVm.StartConnectionFinders();
            // Awaited (WPF ShowDialog blocked here): the finally below must run only after
            // the dialog closes — it releases the VM field and unsubscribes the watcher.
            await _dialogService.ShowDialogAsync<ConnectionDialog>(this, dialogVm);
        }
        finally
        {
            // Release the field reference before closing so the closed VM can be collected and a Close()
            // side effect can't re-enter through the field. Guarantee the dialog unsubscribes from the
            // app-global watcher's collection even if the dialog threw before its window opened (otherwise
            // the lifetime singleton would permanently root the VM). Close() is idempotent, so the normal
            // window-Closing path that already called it is unaffected; best-effort so it can't mask an
            // exception from the show attempt.
            _connectionDialogViewModel = null;
            try
            {
                dialogVm.Close();
            }
            catch (Exception ex)
            {
                _appLogger.Error(ex, "Failed to close connection dialog view model after dialog attempt.");
            }
        }
    }

    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.CloseAppSettings
    private void CloseAppSettings() => IsAppSettingsOpen = false;

    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.RemoveChannel
    private void RemoveChannel(IChannel channelToRemove)
    {
        var device = ConnectionManager.Instance.ConnectedDevices.FirstOrDefault(x => x.DeviceSerialNo == channelToRemove.DeviceSerialNo);
        var channel = device.DataChannels.FirstOrDefault(x => x.DeviceSerialNo == channelToRemove.DeviceSerialNo && x.Name == channelToRemove.Name);
        if (device != null && channel != null)
        {
            LoggingManager.Instance.Unsubscribe(channel);
            device.RemoveChannel(channel);
        }
    }

    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.DisconnectDevice
    private void DisconnectDevice(IStreamingDevice? deviceToDisconnect)
    {
        if (deviceToDisconnect == null)
        {
            return;
        }

        foreach (var channel in deviceToDisconnect.DataChannels)
        {
            if (channel.IsActive)
            {
                LoggingManager.Instance.Unsubscribe(channel);
            }
        }
        ConnectionManager.Instance.Disconnect(deviceToDisconnect);
        _firmwareCoordinator.RemoveFirmwareNotification(deviceToDisconnect);

        if (deviceToDisconnect.Equals(SelectedDevice))
        {
            SelectedDevice = null;
        }
    }

    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.Shutdown
    public void Shutdown()
    {
        foreach (var device in ConnectedDevices)
        {
            device.Disconnect();
        }
    }

    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.UpdateNetworkConfiguration
    public async Task UpdateNetworkConfiguration()
    {
        ResetNetworkSettingsStatus();

        // Guard the happy-path below: a device can disappear while the drawer
        // is open (disconnect, tab switch, etc.), and the underlying
        // UpdateNetworkConfiguration() throws when the connection is gone.
        var device = SelectedDevice;
        if (device == null)
        {
            NetworkSettingsError = "Select a device before applying WiFi settings.";
            return;
        }
        if (!device.IsConnected)
        {
            NetworkSettingsError = "Cannot apply WiFi settings — the device is not connected.";
            return;
        }

        try
        {
            await device.UpdateNetworkConfiguration();
            _ = ShowNetworkSettingsAppliedStatusAsync();
        }
        catch (Exception ex)
        {
            _appLogger.Error(ex, "Failed to update network configuration");
            NetworkSettingsError = "Failed to apply WiFi settings. See the application log for details.";
        }
    }

    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.ResetNetworkSettingsStatus
    private void ResetNetworkSettingsStatus()
    {
        CancelAndDisposeNetworkSettingsCts();
        NetworkSettingsApplied = false;
        NetworkSettingsError = null;
    }

    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.ShowNetworkSettingsAppliedStatusAsync
    private async Task ShowNetworkSettingsAppliedStatusAsync()
    {
        CancelAndDisposeNetworkSettingsCts();
        _networkSettingsAppliedCts = new CancellationTokenSource();
        var token = _networkSettingsAppliedCts.Token;

        NetworkSettingsApplied = true;
        try
        {
            await Task.Delay(TimeSpan.FromSeconds(3), token);
            NetworkSettingsApplied = false;
        }
        catch (TaskCanceledException) { }
    }

    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.CancelAndDisposeNetworkSettingsCts
    private void CancelAndDisposeNetworkSettingsCts()
    {
        var cts = _networkSettingsAppliedCts;
        if (cts == null)
        {
            return;
        }
        _networkSettingsAppliedCts = null;
        try
        {
            cts.Cancel();
        }
        finally
        {
            cts.Dispose();
        }
    }

    /// <summary>
    /// Sets and persists the selected device's friendly name from <see cref="PendingFriendlyName"/>.
    /// Mirrors <see cref="UpdateNetworkConfiguration"/>'s guard/status-feedback shape.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.SetFriendlyName
    [RelayCommand]
    public async Task SetFriendlyName()
    {
        FriendlyNameApplied = false;
        FriendlyNameError = null;

        var device = SelectedDevice;
        if (device == null)
        {
            FriendlyNameError = "Select a device before setting a name.";
            return;
        }
        if (!device.IsConnected)
        {
            FriendlyNameError = "Cannot set the device name — the device is not connected.";
            return;
        }

        var name = PendingFriendlyName?.Trim() ?? string.Empty;
        try
        {
            // SetFriendlyName sends SCPI commands synchronously (serial/TCP write); run it off
            // the UI thread so a slow or stalled device write cannot freeze the UI.
            await Task.Run(() => device.SetFriendlyName(name));

            // The awaited write can be slow, and the user may have switched the drawer to a different
            // device while it ran. The write to THIS device still succeeded, but the drawer state
            // (PendingFriendlyName + the "applied" checkmark) belongs to whatever device is selected
            // NOW — seeding A's name into B's open drawer would clobber B's edit buffer and, on a
            // second Save, write A's name to B's NVM. Mirror the sibling OnSelectedDeviceFriendlyNameChanged
            // guard and only touch drawer state when this device is still the selected one.
            if (device != SelectedDevice)
            {
                return;
            }

            // Show the committed value rather than clearing the field — a blank box after a
            // successful save reads as "it didn't take" even though the device now has the name.
            SeedPendingFriendlyName(name);
            _ = ShowFriendlyNameAppliedStatusAsync();
        }
        catch (ArgumentException ex)
        {
            _appLogger.Warning(ex, $"Rejected friendly name '{name}' for device {device.DeviceDisplayName}");
            FriendlyNameError = ex.Message;
        }
    }

    /// <summary>
    /// Sets <see cref="PendingFriendlyName"/> without marking the edit buffer dirty. Used to seed
    /// the drawer's NAME field when it opens (<c>DevicesPaneViewModel.OpenSettings</c>), after a
    /// successful save, and whenever the selected device's <see cref="IStreamingDevice.FriendlyName"/>
    /// changes and the user has not started editing (<see cref="OnSelectedDeviceChanged"/>).
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.SeedPendingFriendlyName
    internal void SeedPendingFriendlyName(string value)
    {
        _isSeedingPendingFriendlyName = true;
        try
        {
            PendingFriendlyName = value;
        }
        finally
        {
            _isSeedingPendingFriendlyName = false;
        }
        _pendingFriendlyNameDirty = false;
    }

    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.OnPendingFriendlyNameChanged
    partial void OnPendingFriendlyNameChanged(string? value)
    {
        if (!_isSeedingPendingFriendlyName)
        {
            _pendingFriendlyNameDirty = true;
        }
    }

    /// <summary>
    /// Keeps the Devices drawer's NAME field in sync with the selected device's reported
    /// <see cref="IStreamingDevice.FriendlyName"/>, which can arrive asynchronously (fire-and-forget
    /// inbound-message handling) after the drawer has already opened. Re-subscribes on every
    /// selection change so only the currently selected device's updates apply — an update from a
    /// device the user has since deselected/disconnected from must not touch the buffer.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.OnSelectedDeviceChanged
    partial void OnSelectedDeviceChanged(IStreamingDevice? oldValue, IStreamingDevice? newValue)
    {
        if (oldValue is INotifyPropertyChanged oldNotifier)
        {
            oldNotifier.PropertyChanged -= OnSelectedDeviceFriendlyNameChanged;
        }
        if (newValue is INotifyPropertyChanged newNotifier)
        {
            newNotifier.PropertyChanged += OnSelectedDeviceFriendlyNameChanged;
        }
    }

    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.OnSelectedDeviceFriendlyNameChanged
    private void OnSelectedDeviceFriendlyNameChanged(object? sender, PropertyChangedEventArgs e)
    {
        if (e.PropertyName != nameof(IStreamingDevice.FriendlyName))
        {
            return;
        }
        // Don't clobber an in-progress edit, and ignore stale events from a device that is no
        // longer selected (unsubscription races with the async inbound-message pipeline).
        if (_pendingFriendlyNameDirty || sender != SelectedDevice)
        {
            return;
        }
        if (sender is IStreamingDevice device)
        {
            SeedPendingFriendlyName(device.FriendlyName);
        }
    }

    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.ShowFriendlyNameAppliedStatusAsync
    private async Task ShowFriendlyNameAppliedStatusAsync()
    {
        CancelAndDisposeFriendlyNameAppliedCts();
        _friendlyNameAppliedCts = new CancellationTokenSource();
        var token = _friendlyNameAppliedCts.Token;

        FriendlyNameApplied = true;
        try
        {
            await Task.Delay(TimeSpan.FromSeconds(3), token);
            FriendlyNameApplied = false;
        }
        catch (TaskCanceledException) { }
    }

    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.CancelAndDisposeFriendlyNameAppliedCts
    private void CancelAndDisposeFriendlyNameAppliedCts()
    {
        var cts = _friendlyNameAppliedCts;
        if (cts == null)
        {
            return;
        }
        _friendlyNameAppliedCts = null;
        try
        {
            cts.Cancel();
        }
        finally
        {
            cts.Dispose();
        }
    }

    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.BrowseForFirmware
    public async Task BrowseForFirmwareAsync()
    {
        // WinForms OpenFileDialog → StorageProvider picker owned by the app main window
        // (hal: file_pickers).
        if (GetMainWindow() is not { } main)
        {
            return;
        }

        var files = await main.StorageProvider.OpenFilePickerAsync(new FilePickerOpenOptions
        {
            AllowMultiple = false,
            FileTypeFilter = new[] { new FilePickerFileType("Firmware Files (*.hex)") { Patterns = new[] { "*.hex" } } }
        });

        var path = files.Count > 0 ? files[0].TryGetLocalPath() : null;
        if (path != null)
        {
            FirmwareFilePath = path;
        }
    }

