    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.ImportSdCardLogFile
    private async Task ImportSdCardLogFile()
    {
        try
        {
            // Win32 OpenFileDialog → StorageProvider picker owned by the app main window
            // (hal: file_pickers).
            if (GetMainWindow() is not { } main)
            {
                return;
            }

            var files = await main.StorageProvider.OpenFilePickerAsync(new FilePickerOpenOptions
            {
                Title = "Select SD Card Log File to Import",
                AllowMultiple = false,
                // Built from Core's own SupportedExtensions, so a format Core gains is offered
                // here without an edit — and one it drops stops being offered.
                FileTypeFilter = SdCardLogFormatInfo.BuildFilePickerFileTypes()
            });

            var selectedPath = files.Count > 0 ? files[0].TryGetLocalPath() : null;
            if (selectedPath == null) return;

            IsLoggedDataBusy = true;
            LoggedDataBusyReason = $"Importing {System.IO.Path.GetFileName(selectedPath)}...";

            var loggingContext = App.ServiceProvider.GetRequiredService<IDbContextFactory<LoggingContext>>();
            var importer = new SdCardSessionImporter(loggingContext);

            var progress = new Progress<ImportProgress>(p =>
            {
                LoggedDataBusyReason = $"Importing... {p.SamplesProcessed:N0} samples";
            });

            var result = await Task.Run(() =>
                importer.ImportFromFileAsync(selectedPath, null, progress, CancellationToken.None));

            string message;
            if (result.SessionPersisted)
            {
                Dispatcher.UIThread.Invoke(() =>
                {
                    LoggingManager.Instance.LoggingSessions.Add(result.Session);
                });

                message = $"Successfully imported {System.IO.Path.GetFileName(selectedPath)}";

                // A persisted session can still owe the user a word — an overwrite whose old
                // session could not be removed leaves a duplicate they have to clear by hand.
                if (result.OutcomeGuidance.Length > 0)
                {
                    message += $"\n\n{result.OutcomeGuidance}";
                }
            }
            else
            {
                // Nothing threw, but no finished session came of it — an empty log, or samples
                // that could not be recorded as a completed session. The message must not claim a
                // session was created; the importer supplies the sentence that says which it was,
                // so this and the device-import dialogs cannot drift apart.
                message = $"{System.IO.Path.GetFileName(selectedPath)}: {result.OutcomeGuidance}";
            }

            var timestampWarning = result.TimestampQuality.BuildUserWarning();
            if (timestampWarning != null)
            {
                message += $"\n\nWarning: {timestampWarning}";
            }

            await ShowMessage("Import Complete", message, MessageBoxButton.OK);
        }
        catch (OperationCanceledException)
        {
            // User cancelled — do nothing
        }
        catch (Exception ex)
        {
            _appLogger.Error(ex, "Error importing SD card log file");
            await ShowMessage("Import Failed",
                "Failed to import the selected file. Please verify the file is a valid SD card log file and try again.",
                MessageBoxButton.OK);
        }
        finally
        {
            IsLoggedDataBusy = false;
            LoggedDataBusyReason = string.Empty;
        }
    }

