    /// <summary>
    /// Adds a standing notification when USB hotplug-removal detection is not running on a platform
    /// that has USB serial hardware, so the user learns that unplugging a connected device will not
    /// be noticed instead of being left to infer it from a stale connected state (issue #90).
    /// Adds nothing on the platforms where detection is working, and nothing on the mobile heads,
    /// which have no serial transport to watch.
    /// </summary>
    private void ReportHotplugDetectionUnavailable()
    {
        var message = ConnectionManager.Instance.HotplugDetectionUnavailableMessage;
        if (string.IsNullOrEmpty(message))
        {
            return;
        }

        // DeviceSerialNo is deliberately left unset (null): this is an app-level condition with no
        // owning device, and a null serial is what exempts it from RemoveNotification's per-device
        // pruning. Link is left unset too — the flyout hides its "Click here" button when it is null.
        NotificationList.Add(new Notifications
        {
            IsFirmwareUpdate = false,
            Message = message
        });
        NotificationCount = NotificationList.Count;
    }

    /// <summary>
    /// Adds a standing notification when startup found <c>DAQiFiDatabase.db</c> unreadable and moved
    /// it aside. Without it the app looks fine and the Logged Data pane is just empty, which reads
    /// as "my sessions were deleted" rather than "the file was damaged and is still on disk here".
    /// Adds nothing on the normal path, where no database was quarantined.
    /// </summary>
    private void ReportQuarantinedDatabase()
    {
        if (DatabaseMigrator.DescribeQuarantineForUser() is not { } message)
        {
            return;
        }

        // Null DeviceSerialNo for the same reason as ReportHotplugDetectionUnavailable above: an
        // app-level condition with no owning device, which is what exempts it from
        // RemoveNotification's per-device pruning so it survives the next UpdateUi pass.
        NotificationList.Add(new Notifications
        {
            IsFirmwareUpdate = false,
            Message = message
        });
        NotificationCount = NotificationList.Count;
    }

    /// <summary>
    /// Tells the user that flipping the logging toggle did not start a session, and why. Called from
    /// the <see cref="IsLogging"/> setter after <c>LoggingManager</c> reports a failed start.
    /// </summary>
    /// <remarks>
    /// Both surfaces, deliberately: the dialog because the user just clicked something and watched
    /// it snap back, and the standing notification (the shape <see cref="ReportQuarantinedDatabase"/>
    /// established) because that is what is still readable once the dialog is dismissed.
    /// </remarks>
    private void ReportLoggingCouldNotStart(string message)
        => ReportLoggingProblem("Cannot Start Logging", message, isDefect: true);

    /// <summary>
    /// Tells the user that a logging command did not do what the click asked for, and why.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Both surfaces, deliberately: the dialog because the user just clicked something and watched
    /// it snap back, and the standing notification (the shape <see cref="ReportQuarantinedDatabase"/>
    /// established) because that is what is still readable once the dialog is dismissed.
    /// </para>
    /// <para>
    /// The title is a parameter because #214 gave this three more callers with three different
    /// things to say — a start that no device accepted, a start some devices sat out, a stop some
    /// devices did not confirm, and a mode switch that was rolled back. They are not all "Cannot
    /// Start Logging", and a partial start in particular is not a failure at all.
    /// </para>
    /// </remarks>
    /// <param name="title">Dialog title; also the first line of the standing notification.</param>
    /// <param name="message">What happened, in the user's terms.</param>
    /// <param name="isDefect">
    /// <c>true</c> to log at Error, which raises a Sentry issue. Only the failed session row (#183)
    /// sets it: that is the app's own storage failing. A device declining a command is a device or
    /// environmental condition the app cannot prevent — no card, no link, wrong transport — and the
    /// repo routes those to Warning so they do not file issues, the same rule
    /// <see cref="SdCardFailureClassifier"/> applies.
    /// </param>
    private void ReportLoggingProblem(string title, string message, bool isDefect = false)
    {
        if (isDefect)
        {
            _appLogger.Error(message);
        }
        else
        {
            _appLogger.Warning($"{title}: {message}");
        }

        // Null DeviceSerialNo, as above: an app-level condition with no owning device, which exempts
        // it from RemoveNotification's per-device pruning. A refusal can name several devices, so it
        // has no single owner to prune it by either.
        //
        // The message alone, not the title with it: the notification list is a flat list of
        // sentences, and every message passed here is written to stand on its own in it.
        NotificationList.Add(new Notifications
        {
            IsFirmwareUpdate = false,
            Message = message
        });
        NotificationCount = NotificationList.Count;

        // Fire-and-forget for the same reason the disk-space gate in this same setter does it: the
        // toggle's two-way binding is mid-write, so there is nothing here that can await a modal.
        // The dialog's own failures are caught rather than left as an unobserved task fault.
        _ = ShowLoggingProblem(title, message);
    }

    /// <summary>Shows the logging-problem dialog, and never lets its own failure escape.</summary>
    private async Task ShowLoggingProblem(string title, string message)
    {
        try
        {
            await _messageBoxService.ShowAsync(message, title, MessageBoxButton.OK, MessageBoxImage.Warning);
        }
        catch (Exception ex)
        {
            _appLogger.Error(ex, "Failed to show the logging problem dialog");
        }
    }

    /// <summary>
    /// Prunes notifications whose owning device is no longer connected. General-purpose
    /// (covers both app-version and firmware notifications); firmware-specific add/remove
    /// now lives in the firmware coordinator. Notifications with no owning device — created with a
    /// null serial — are exempt so they survive this cleanup.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.DaqifiViewModel.RemoveNotification
    internal void RemoveNotification()
    {
        foreach (var notification in NotificationList.ToList())
        {
            // A null serial marks a notification with no owning device: the app-update notice (see the
            // "NotificationCount" case in UpdateUi) and the hotplug-unavailable notice. Exempt exactly
            // that — a null serial — or they would be removed on the same UpdateUi pass that adds them
            // (this runs at the end of every UpdateUi) and never appear. Device-owned notifications
            // still go through the disconnect check below, even if a device reports an empty serial.
            if (notification.DeviceSerialNo is null)
            {
                continue;
            }

            var deviceIsDisconnected = !ConnectionManager.Instance.ConnectedDevices
                .Any(device => device.DeviceSerialNo == notification.DeviceSerialNo);

            if (deviceIsDisconnected)
            {
                NotificationList.Remove(notification);
            }
        }
        NotificationCount = NotificationList.Count;
    }

